def main():
    nodes = []
    for i, n, la, lo, rk in NODES:
        xy = P(la, lo)
        nodes.append({"id": i, "name": n, "x": xy[0], "y": xy[1], "risk": rk, "adj": [b if a == i else a for a, b in EDGES if i in (a, b)]})
    ports = []
    for pid, cc, reg, name, la, lo, w, node, kind, atl in PORTS:
        xy = P(la, lo)
        ports.append({"id": pid, "cc": cc, "reg": reg, "name": name, "x": xy[0], "y": xy[1], "w": float(w), "node": node, "kind": kind, "atl": atl})
    d = {"nodes": nodes, "ports": ports, "classes": CLASSES, "carrier": CARRIER, "navy0": NAVY0, "sea_share": SEA_SHARE, "access": ACCESS}
    datio.dump(os.path.join(ROOT, "data", "fleet.dat"), d)
    print("ok", len(nodes), "узлов", len(ports), "портов")
main()
